// ConfigurationToPB converts Configuration to Configuration.
func ConfigurationToPB(r device.Configuration) (*Configuration, error) {
	analogInputVal, err := AnalogInputPortsToPB(r.AnalogInput)
	if err != nil {
		return nil, err
	}
	pb := &Configuration{
		Name:        r.Name,
		Identifier:  r.Identifier,
		AnalogInput: analogInputVal,
	}
	if r.AnalogOutput != nil {
		pb.AnalogOutput = make(map[uint32]*AnalogOutputChannels, len(r.AnalogOutput))
		for k, v := range r.AnalogOutput {
			converted, err := AnalogOutputChannelsToPB(v)
			if err != nil {
				return nil, err
			}
			pb.AnalogOutput[uint32(k)] = converted
		}
	}
	if r.CounterInput != nil {
		pb.CounterInput = make(map[uint32]*CounterInputChannels, len(r.CounterInput))
		for k, v := range r.CounterInput {
			converted, err := CounterInputChannelsToPB(v)
			if err != nil {
				return nil, err
			}
			pb.CounterInput[uint32(k)] = converted
		}
	}
	if r.DigitalInput != nil {
		pb.DigitalInput = make(map[uint32]*DigitalInputChannels, len(r.DigitalInput))
		for k, v := range r.DigitalInput {
			converted, err := DigitalInputChannelsToPB(v)
			if err != nil {
				return nil, err
			}
			pb.DigitalInput[uint32(k)] = converted
		}
	}
	if r.DigitalOutput != nil {
		pb.DigitalOutput = make(map[uint32]*DigitalOutputChannels, len(r.DigitalOutput))
		for k, v := range r.DigitalOutput {
			converted, err := DigitalOutputChannelsToPB(v)
			if err != nil {
				return nil, err
			}
			pb.DigitalOutput[uint32(k)] = converted
		}
	}
	return pb, nil
}

// ConfigurationFromPB converts Configuration to Configuration.
